import os
import re
from subprocess import PIPE, Popen

from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output,
)

from taf.rfrl.procedures.resources.python.parser.exceptions import (
    IncorrectFileExtension,
    CoreDumpDecodingError,
)


@log_input_and_output
def decrypt_coredump_file(path_to_coredump):
    """
    Decrypts given coredump file and returns data as string ('utf-8' format).

    :param path_to_coredump: absolute path with filename and extension to coredump file, e.g. /tmp/core.pcap.p7b
    :type path_to_coredump: str

    :return: decrypted coredump file, e.g.:
                PKCS7:
                  type: pkcs7-envelopedData (1.2.840.113549.1.7.3)
                  d.enveloped:
                    version: 0
                    recipientinfo:
                        version: 0
                        issuer_and_serial:
                          issuer: C=XX, L=Default City, O=Default Company Ltd
                          serial: 9427676536812710904
                        key_enc_algor:
                          algorithm: rsaEncryption (1.2.840.113549.1.1.1)
                          parameter: NULL
                        enc_key:
                          0000 - 52 44 72 74 a5 49 c6 a0-8a de 1a ce 71 81 7e   RDrt.I......q.~
                          000f - 80 f8 2f 8b 89 98 0a 9a-36 1a f9 5d 9a 9f ac   ../.....6..]...
                          001e - f7 d5 f0 9f 2d fa b1 ed-19 5d 2a a8 2e 94 6b   ....-....]*...k
                          002d - 9b 94 2b 81 b7 f4 1d 7a-89 33 68 bf f9 cb 02   ..+....z.3h....
                          003c - 13 5a 06 fa 58 74 be 5e-7f cf 11 cf d0 16 ae   .Z..Xt.^.......
                          004b - d7 56 07 ad 51 28 0f 79-56 bd 54 17 c7 f7 2a   .V..Q(.yV.T...*
                          005a - 14 ff ef ad ef 11 6c 73-ab e2 c1 26 97 e7 40   ......ls...&..@
    :rtype: str

    :raises FileNotFoundError when given coredump path is incorrect
    :raises IncorrectFileExtension when coredump file extension is incorrect
    """
    _check_coredump_file(path_to_coredump)

    os_command = f"openssl pkcs7 -in {path_to_coredump} -inform DER -print | more"

    subproc = Popen(os_command, shell=True, stdout=PIPE, stderr=PIPE)
    stdout, stderr = subproc.communicate()

    if stderr:
        raise CoreDumpDecodingError(stderr.decode("utf-8"))
    else:
        return stdout.decode("utf-8")


def get_encryption_key_from_decrypted_coredump(decrypted_coredump):
    """
    Gets encryption key from decrypted coredump data.

    :param decrypted_coredump: decrypted coredump file data, returned by 'decrypt_coredump_file' function.
    :type decrypted_coredump: str

    :return: encryption coredump key, e.g.:
                          0000 - 52 44 72 74 a5 49 c6 a0-8a de 1a ce 71 81 7e   RDrt.I......q.~
                          000f - 80 f8 2f 8b 89 98 0a 9a-36 1a f9 5d 9a 9f ac   ../.....6..]...
                          001e - f7 d5 f0 9f 2d fa b1 ed-19 5d 2a a8 2e 94 6b   ....-....]*...k
                          002d - 9b 94 2b 81 b7 f4 1d 7a-89 33 68 bf f9 cb 02   ..+....z.3h....
                          003c - 13 5a 06 fa 58 74 be 5e-7f cf 11 cf d0 16 ae   .Z..Xt.^.......
                          004b - d7 56 07 ad 51 28 0f 79-56 bd 54 17 c7 f7 2a   .V..Q(.yV.T...*
                          005a - 14 ff ef ad ef 11 6c 73-ab e2 c1 26 97 e7 40   ......ls...&..@
    :rtype: str

    :raises FileNotFoundError when incorrect 'enc_key' found in coredump decrypted data.
    """
    enc_key = decrypted_coredump.split("enc_key:")

    if len(enc_key) == 1:
        raise CoreDumpDecodingError(f"Decrypted coredump does not contain 'enc_key' phrase: {decrypted_coredump}")
    elif len(enc_key) > 2:
        raise CoreDumpDecodingError(f"Decrypted coredump contains more than one 'enc_key' phrase: {decrypted_coredump}")

    return enc_key[-1].lstrip()


@log_input_and_output
def verify_coredump_encryption_key(enc_key, num_lines_to_verify=5):
    """
    Verifies if cordump's encryption key lines have correct format.
    Example of correct line:
        0000 - 52 44 72 74 a5 49 c6 a0-8a de 1a ce 71 81 7e   RDrt.I......q.~

    :param enc_key: encryption key returned by 'get_encryption_key_from_decrypted_coredump' function
    :type enc_key: str
    :param num_lines_to_verify: number of first encryption key lines to verify, defaults to 5
    :type num_lines_to_verify: int or str
    :return: True if all designated first lines of coredump's encryption key have correct format, False otherwise.
    :rtype: bool
    """
    coredump_enc_key_lines = [line.lstrip().rstrip() for line in enc_key.split("\n")
                              if line and line != " "][:int(num_lines_to_verify)]

    key_line_pattern = r"^[\w.]{4}\s-\s([\w.]{2}\s){7}[\w.]{2}-[\w.]{2}(\s[\w.]{2}){6}"

    for key_line in coredump_enc_key_lines:
        if not re.match(key_line_pattern, key_line):
            return False

    return True


@log_input_and_output
def _check_coredump_file(path_to_coredump):
    """
    Checks given coredump file path and extension.

    :param path_to_coredump: absolute path with filename and extension to coredump file, e.g. /tmp/core.pcap.p7b
    :type path_to_coredump: str

    :raises FileNotFoundError when given coredump path is incorrect
    :raises IncorrectFileExtension when coredump file extension is incorrect
    """
    if not os.path.isfile(path_to_coredump):
        raise FileNotFoundError(f"Incorrect coredump file path: {path_to_coredump}")

    filename = os.path.basename(path_to_coredump)

    if filename.split(".")[-1] != "p7b":
        raise IncorrectFileExtension(f"Incorrect coredump file extension: {filename}")
